return {
    [" 铁十字街售卖香煎肉鱼、牡蛎汤、小松饼、鳗鱼汤、姜汁啤酒等平价美食。"] = "На Айрон-Кросс-стрит продаются доступные деликатесы, такие как жареное мясо и рыба, устричный суп, маленькие блинчики, суп из угря и имбирное пиво.",
    ["“2”级封印物，危险，须谨慎且节制地利用……"] = "Запечатанный Артефакт «2» степени, опасен, использовать нужно осторожно и умеренно...",
    ["“不眠者”途径的非凡者需要通过吟唱诗篇来影响周围生灵。"] = "Находящимся за пределами пути «Бессонных» необходимо воздействовать на окружающих живых существ, распевая стихи.",
    ["“命运天使”乌洛琉斯，命运途径的天使之王，远古太阳神的追随者。"] = "«Ангел Судьбы» Уроборос, Король Ангелов Пути Судьбы, последователь Древнего Бога Солнца.",
    ["“夜之国”由古神的后裔建立，现已毁灭。"] = "«Земля Ночи» была основана потомками древних богов и сейчас уничтожена.",
    ["“我没有背叛白银城……”曾经的话语消散在黄昏中。"] = "«Я не предал Город Серебра…» Сказанное однажды слово рассеялось в сумерках.",
    ["“暗天使”萨斯利尔的躯壳沉睡于巨人王庭， 遭到了混沌海的侵蚀。"] = "Оболочка «Темного ангела» Сасрира покоится во дворе Короля Гигантов, будучи разрушена Морем Хаоса.",
    ["【猎杀时刻】活动期间，击败王城中的守卫者，可获得大量猩红遗物材料！"] = "Во время события [Время охоты] победа над стражами Королевского города может принести вам большое количество алых реликвий!",
    ["【猎杀时刻】活动期间，王城中心将开放命运人偶召唤。"] = "Во время события [Время охоты] в центре Королевского города откроется призыв Марионеток Судьбы.",
    ["【猎杀时刻】活动期间，风险与收益并存！击杀敌方可掠夺双倍段位胜点，反之亦然。"] = "Во время события [Время охоты] риски и награды сосуществуют! Убийство врагов может принести двойное количество очков ранга, и наоборот.",
    ["一个女孩正在等待，等待你将最后的心愿归还给她。"] = "Девушка ждет, ждет, когда ты ответишь ей на ее последнее желание.",
    ["一个恩赐，或者，一个诅咒。"] = "Дар или проклятие.",
    ["一个被诡异力量侵蚀的宝箱，正等待净化。"] = "Сундук с сокровищами, разрушенный странной силой, ожидающий очищения.",
    ["一座伟岸的蒸汽之城，一个登月的神奇构想，一缕熟悉的知识残影……"] = "Величественный паровой город, чудесная концепция высадки на Луну, знакомая затянувшаяся тень знания...",
    ["一张写满救命的门票指向了一座诡异的剧院，你决定一探究竟……"] = "Билет с просьбами о помощи указывает на причудливый театр; вы решаете провести расследование...",
    ["一本诡异的人皮书，等待着下一个被选中的人。"] = "Странная книга из человеческой кожи ждет следующего человека, которого выберут.",
    ["一条铁路自西而东贯穿金秋湖，从廷根直达贝克兰德。"] = "Через озеро Золотая Осень проходит железная дорога с запада на восток, прямо из Тингена в Баклунд.",
    ["万物皆有神性。"] = "Все вещи обладают божественностью.",
    ["三枚相同的棋子相遇，将凝成更强大的历史投影。"] = "Когда встретятся три одинаковые фигуры, они сольются в более мощную проекцию истории.",
    ["不同途径组成的队伍战斗时策略应当有所区别，例如“门”途径的学徒更适合突进切入。"] = "Стратегии должны различаться, когда сражаются команды, состоящие из разных направлений; например, Ученики пути «Дверь» больше подходят для вторжения.",
    ["不属于这个时代的愚者，灰雾之上的神秘主宰，执掌好运的黄黑之王。"] = "Шут, не принадлежащий этой эпохе, таинственный правитель над серым туманом, Король Желтого и Черного, приносящий удачу.",
    ["不要乱扔秘偶，会被追踪的。"] = "Не разбрасывайте марионеток где попало — вас выследят.",
    ["两个征服之碑均被任意进攻方占领后，战争之门开启。"] = "Как только оба Знамени Завоевания будут заняты любой атакующей стороной, Врата Войны откроются.",
    ["丰饶之树原是大地母神教会的封印物，自背誓之战后，就一直存在于此地。"] = "Древо Изобилия изначально было Запечатанным Артефактом Церкви Матери-Земли и пребывает на этом месте со времен Войны Нарушенной Клятвы.",
    ["为强力棋子佩上非凡装备，一子可定胜负。"] = "Оснастите сильную фигуру потусторонним снаряжением — одна фигура может решить исход партии.",
    ["主宰争锋对局达到一分钟和两分钟时，攻击力将获得提升，可利用该效果拿下对局。"] = "Когда матч Dominator's Clash достигнет одной и двух минут, сила атаки увеличится; вы можете использовать этот эффект, чтобы выиграть матч.",
    ["主宰争锋每局都可以使用两次特殊回复药。"] = "В каждой игре Dominator's Clash вы можете использовать два специальных зелья восстановления.",
    ["主宰争锋玩法内非凡者的实力水平是经过平衡的，非常公平。"] = "Уровень силы экстраординарных персонажей в игровом процессе Domination Clash сбалансирован и очень справедлив.",
    ["主峰曾经有人类居住的痕迹，在某一天这里的居民瞬间蒸发了。"] = "На главной вершине были следы человеческого жилья, и однажды жители мгновенно испарились.",
    ["乌托邦剧院是和“愚者”先生记忆相关的封印物，母神试图污染它，以影响祂的精神……"] = "Театр Утопия — это Запечатанный Артефакт, связанный с памятью господина \"Шута\". Мать-богиня пытается осквернить его, чтобы повлиять на Его дух...",
    ["乌黯魔狼很擅长躲藏，深谙占卜家途径的生存之道，直到祂遇到愚者。"] = "Тёмный демонический волк отлично умел прятаться и хорошо знал секреты выживания Пути Провидца, пока не встретил Шута.",
    ["乘坐蒸汽火车可以更快速的到达前线。"] = "Поездка на паровозе позволит вам быстрее добраться до линии фронта.",
    ["五月庄园内有恶犬，请勿触摸，必要时可投喂苹果。"] = "В Мэй-Мэноре есть злобные собаки; пожалуйста, не трогайте их и при необходимости кормите яблоками.",
    ["亚巴顿的老巢，亡灵的源头。终结这一切，或是成为他的又一件收藏。"] = "Логово Абаддона, источник нежити. Покончите со всем этим или станьте еще одной из его коллекций.",
    ["人机模式可通过轮盘调整机器人的战斗模式。"] = "В режиме с ботами боевой режим союзников можно настраивать с помощью селектора.",
    ["人类想要成为非凡者，一般都需要服用魔药。"] = "Чтобы стать Потусторонним, людям обычно нужно принять Зелье.",
    ["众神之巅对局时间超过一定时间，攻击力将会提升。"] = "Если матч «Пик богов» превысит определенное время, сила атаки увеличится.",
    ["众神之巅淘汰赛开启前，可为自己心仪的队伍投票。"] = "Перед началом турнира «Пик богов» вы можете проголосовать за любимую команду.",
    ["会长、外交官、理事可使用指挥技能扭转战局，改写整场比赛！"] = "Президент, дипломат и директор могут использовать командные навыки, чтобы переломить ход боя и переписать исход всего матча!",
    ["传说这里藏着安提哥努斯家族复兴的秘密宝藏。"] = "Легенда гласит, что здесь спрятано тайное сокровище возрождения семьи Антигона.",
    ["传闻每个城市都有关于失控非凡者事件的档案记录，这些档案从不轻易示人。"] = "Ходят слухи, что в каждом городе есть архивные записи о вышедших из-под контроля инцидентах с Потусторонним, и эти файлы никогда не покажут другим.",
    ["位于同一家族的玩家参与副本时，可以获得属性加成与额外复活次数。"] = "Когда игроки из одной семьи участвуют в подземелье, они могут получить бонусы к характеристикам и дополнительное количество воскрешений.",
    ["你做了一个古怪的梦，梦中的你成为了一名骑士……"] = "Тебе приснился странный сон, и во сне ты стал рыцарем...",
    ["你可以伪装成任何人，但只能是自己。"] = "Вы можете маскироваться под кого угодно, но быть только самим собой.",
    ["你在恍惚中潜入花海之湖底，这里竟藏着两个名为“秩序”与“混乱”的世界……"] = "Вы в трансе ныряете на дно моря цветов, и здесь скрываются два мира под названием «порядок» и «хаос»…",
    ["你在拉姆德小镇找到一间充满灵异秘术的屋子，里面竟是一个凶案现场……"] = "В маленьком городке Рамд вы нашли дом, полный мистики, а он оказался местом преступления...",
    ["使用灵视可以发现附近特殊的物品。"] = "Используйте духовное зрение, чтобы обнаружить поблизости особые предметы.",
    ["先祖铠甲的主人伯德温·威瑟尔，曾参与背誓之战，凯旋后获得无数封赏。"] = "Болдуин Уэтерелл, владелец Доспехов Предков, участвовал в Войне нарушенной Клятвы и после своего триумфального возвращения получил бесчисленные награды.",
    ["光就是一切的意义。"] = "Свет – это смысл всего.",
    ["克莱恩·莫雷蒂曾受导师推荐，来廷根大学面试讲师。"] = "Однажды наставник порекомендовал Клейну Моретти пройти собеседование на должность лектора в Тингенском университете.",
    ["克莱恩毕业于霍伊大学历史系。"] = "Клейн окончил исторический факультет Хойского университета.",
    ["入夜前，人们会回到家中，如果此时身在外面，很可能会遭遇到灵异事件。"] = "Еще до наступления темноты люди возвращаются домой; если вы находитесь на улице в это время, вы, вероятно, столкнетесь со сверхъестественными событиями.",
    ["冥界是远古死神在灵界内开辟出来的特殊地方。"] = "Подземный мир — это особое место, созданное древним Богом Смерти в Мире Духов.",
    ["几千年过去，巨人们一直在寻找家乡。这条路，除非抵达终点，否则永不停止。"] = "Прошли тысячи лет, а великаны искали свой родной город. Эта дорога никогда не остановится, пока не дойдет до конца.",
    ["初代拉姆德男爵的画像在此处被发现。"] = "Здесь был обнаружен портрет первого барона Ламуда.",
    ["剧院中层层叠叠的回廊，每一层都是对秘偶小镇的部分重现。"] = "Каждый из многоуровневых коридоров театра является частичным воссозданием маленького городка-марионетки.",
    ["勇者对决中死亡后不可复活，把握每一次交锋机会。"] = "После смерти в дуэли храбрецов воскрешение невозможно. Используйте каждый шанс в схватке.",
    ["勇者对决采用1对1单挑，双方使用自身真实属性。"] = "Дуэль храбрых проходит в формате 1 на 1, оба участника используют свои истинные характеристики.",
    ["占卜俱乐部位于豪尔斯街13号二楼。"] = "Клуб гадания расположен на втором этаже по адресу Zoutland Street, 13.",
    ["占卜家途径：解读启示，敬畏命运。"] = "Путь Провидца: Интерпретируйте откровения, уважайте судьбу.",
    ["卡尔·埃德加痴迷于收藏玩偶……"] = "Карл Эдгар одержим коллекционированием кукол...",
    ["厄水的巨龟居住在湖底，受污染变得狂躁异常。"] = "Гигантская черепаха из воды стихийного бедствия обитает на дне озера и из-за загрязнения стала ненормально раздражительной.",
    ["双人模式中，可通过记忆碎片界面的【记忆回溯】将碎片给出，副本内玩家可以拾取"] = "В режиме дуэта вы можете передавать фрагменты с помощью функции [Восстановление памяти] в интерфейсе фрагментов памяти, которые затем могут подобрать игроки в подземелье.",
    ["受污染的金秋湖，发生了丰收的危机和动物的异变。"] = "Загрязненное озеро Золотая Осень пережило кризис урожая и мутации животных.",
    ["古堡主体结构保留第四纪末至第五纪初的建筑特色。"] = "Основная структура замка сохраняет архитектурные особенности конца Четвертой – начала Пятой Эпохи.",
    ["古堡地下室埋葬着某位神的后裔，也是阿兹克·艾格斯的孩子。"] = "В подвале старинного замка погребён потомок одного из богов — дитя Азика Эггерса.",
    ["古堡大厅高阔但采光昏暗，窗小而高，石柱支撑穹顶，地下室入口隐蔽。"] = "Зал замка высокий и широкий, но тускло освещенный, с маленькими высокими окнами, каменными колоннами, поддерживающими купол, и скрытым входом в подвал.",
    ["可在【设置】-【画面】-【画面效果】中选择在进入剧情模式时隐藏某些外观部件。"] = "Вы можете скрыть определенные косметические детали при входе в сюжетный режим в [Настройки] — [Графика] — [Визуальные эффекты].",
    ["可将目标筛选策略设置为优先血量最低，方便锁定残血目标。"] = "Вы можете установить стратегию фильтрации целей, чтобы отдавать приоритет наименьшему уровню здоровья, что упрощает захват целей с низким уровнем здоровья.",
    ["史上最强舞王VS现代最强舞王，会赢吗？"] = "Величайший танцор в истории против величайшего танцора современности: кто победит?",
    ["合理保留位移和控制技能，既可追击，也可应对反击。"] = "Разумно приберегайте навыки перемещения и контроля: они пригодятся и для преследования, и для ответа на контратаку.",
    ["合理装配人脉技能，可以显著提升角色强度。"] = "Разумное использование навыков связи может значительно увеличить силу персонажа.",
    ["名为泰德的家庭教师受邀来到庄园，却声称拥有治疗小子爵的方法。"] = "В поместье был приглашен наставник по имени Тед, но он утверждал, что у него есть способ лечить молодого виконта.",
    ["命运天赋的占卜家推荐携带纸牌飞刀、塔罗牌阵、奇迹牌雨、卡牌大师进行战斗。"] = "Провидцу с талантом «Судьба» рекомендуется иметь при себе в бою Card Flying Dagger, Array Tarot, Miracle Card Rain и Card Master.",
    ["和缔结誓约的伙伴一起挑战，会获得属性、复活次数和秘偶精粹等额外增益。"] = "Бросив вызов партнеру, с которым вы заключили Завет, вы получите дополнительные бонусы, такие как статистика, количество воскрешений и сущность марионетки.",
    ["四皇为所罗门帝国的黑皇帝、图铎王朝的血皇帝、特伦索斯特帝国的夜皇和南大陆的冥皇。"] = "Четырьмя императорами были Черный император Империи Соломона, Кровавый император династии Тюдоров, Император Ночи Империи Трунсост и Император Смерти Южного континента.",
    ["四皇之战是第四纪的一场改变世界局势的战争，神灵在这场战争中亲自下场。"] = "Война Четырех Императоров — это война Четвертой Эпохи, изменившая ситуацию в мире, и в этой войне лично участвовали боги.",
    ["因灵魂被分割，阿兹克·艾格斯陷入死亡与复活的轮回。"] = "Поскольку его душа была расколота, Азик Эггерс попал в цикл смерти и воскрешения.",
    ["圣裁天赋的歌颂者推荐携带无暗之枪、净化之斩、飓风斧、圣光净化进行战斗。"] = "Барду с талантом «Святой вердикт» рекомендуется иметь при себе в бою «Незатененное копье», «Очищающий удар», «Ураганный топор» и «Очищение святого света».",
    ["圣赛琳娜教堂，位于北区，是黑夜教会在廷根市的主教堂。"] = "Собор Святой Селены, расположенный в Северном районе, является главным собором Вечной церкви в Тингене.",
    ["在“众神纪元”，神灵时常展现神迹。"] = "В «Эпоху Богов» божества часто совершали чудеса.",
    ["在“黑暗纪元”，人类是巨人、精灵、血族的附庸。"] = "В «Темную эпоху» люди были вассалами гигантов, эльфов и расы крови.",
    ["在势力战前期，占领并保护己方战争石碑是最重要的策略。"] = "На ранней стадии Войны фракций захват и защита своей Стелы войны являются важнейшей стратегией.",
    ["在命运的戏耍下，血红的阴影逐渐笼罩了五月庄园。"] = "По прихоти насмешливой судьбы кроваво-красная тень постепенно окутала поместье Мэй.",
    ["在商会购买非凡经验，提升等级，上阵更多棋子。"] = "Покупайте в Торговой палате опыт Потусторонних, повышайте уровень и выставляйте больше фигур.",
    ["在四方联赛战场中，途径压制同样对幻影守卫有效。"] = "На поле боя Лиги четырех путей «Подавление пути» также эффективно против Фантомных стражей.",
    ["在地图各处收集到的异象之物，可以到俱乐部的伦纳德处用来换取奖励。"] = "Предметы Феномена, собранные по карте, можно обменять на награды у Леонарда в Клубе.",
    ["在终末猎杀场地中，队伍、团队、同俱乐部成员将受到战斗保护，团队联盟不受战斗保护！"] = "На арене «Финальная охота» команды, группы и коллеги-члены клуба получат боевую защиту; командные альянсы не получают боевой защиты!",
    ["在罗塞尔统治期间，“工匠之神”更名为“蒸汽与机械之神”。"] = "Во время правления Розеля «Бог Ремесел» сменил имя на «Бог Пара и Машин».",
    ["在这里你甚至能见到跳舞的卷毛狒狒。"] = "Здесь можно даже увидеть танцующих кудрявых павианов.",
    ["大地母神教会认为，每个生命都是“植物”。"] = "Церковь Матери-Земли верит, что каждая жизнь — это «растение».",
    ["失控的秘偶们残留着生前的记忆，拾取记忆碎片或许会对你的调查有所帮助。"] = "Вышедшие из-под контроля марионетки сохраняют воспоминания о событиях, произошедших до их смерти; сбор фрагментов воспоминаний может помочь в вашем расследовании.",
    ["奇迹只能一时，命运总是漫长。"] = "Чудеса временны; судьба всегда длинна.",
    ["如今的拉姆德古堡外墙坍塌，绿植缠绕。"] = "Сегодня внешние стены замка Ламуд рухнули и покрыты зеленью.",
    ["如果你看到一只疯狂的红色眼睛在窥视着你……请一定小心！"] = "Если вы видите, что на вас смотрит сумасшедший красный глаз... будьте осторожны!",
    ["子爵一家会在每年五月开放庄园，邀请领地内的居民共享芬芳。"] = "Семья виконта открывает поместье каждый май, чтобы пригласить жителей территории поделиться ароматом.",
    ["学徒途径：我来到，我看见，我记录。"] = "Путь ученика: Пришёл, увидел, записал.",
    ["学者天赋的窥秘人推荐携带知识逐人、光之折射、星沙、岁月的棋局进行战斗。"] = "Тайному жрецу с талантом «Ученый» рекомендуется иметь при себе в бою «Поиск знаний», «Преломление света», «Звездный песок» и «Гамбит веков».",
    ["安抚天赋的观众推荐携带梦境分析、心灵引导、心理暗示、意识操纵进行战斗。"] = "Зрителю с талантом «Умиротворение» рекомендуется использовать в бою «Анализ сновидений», «Ментальное руководство», «Психологическое внушение» и «Манипулирование сознанием».",
    ["安提哥努斯家族在第四纪的所罗门帝国有着显赫地位，但这段历史却被迷雾笼罩着……"] = "Семья Антигонуса занимала видное положение в Империи Соломона в Четвертую эпоху, но эта история окутана туманом...",
    ["安提哥努斯家族笔记，曾由密修会持有，因为一次意外而遗失。"] = "Семейные заметки Антигона когда-то принадлежали семье Авраама, но были утеряны из-за несчастного случая.",
    ["家族遗传病夺走了子爵夫人的丈夫，又将夺走她的孩子。"] = "Наследственная болезнь забрала мужа виконтессы и заберет ее ребенка.",
    ["密修会每一次出现，都在追逐安提哥努斯家族的遗物。"] = "Каждый раз, когда появляется семья Авраама, они гоняются за реликвиями семьи Антигона.",
    ["对局开始后每4分钟刷新高倍守卫结算，抢占归属可获4或6倍积分。"] = "Поселения Стражей с высоким множителем обновляются каждые 4 минуты после начала матча; заявление о праве собственности может принести в 4 или 6 раз больше очков.",
    ["封印物“2-049”会让周围的人变得迟缓，注意队友的动作，及时解救！"] = "Запечатанный артефакт «2-049» сделает людей вокруг него вялыми; обращайте внимание на движения своих товарищей по команде и вовремя спасайте их!",
    ["将技能搭配、封印物、非凡天赋存储为装配方案，可以进行快速切换。"] = "Сохранение комбинаций навыков, запечатанных артефактов и талантов Потусторонний в качестве загрузки позволяет быстро переключаться.",
    ["就算没有意义，有些事情还是得去做。"] = "Даже если это бессмысленно, кое-что все равно придется сделать.",
    ["尸潮如瀑，自山间倾泻。死亡如影随形，生路只有一条。"] = "Поток трупов льется с гор водопадом. Смерть следует, как тень; есть только один путь к выживанию.",
    ["山脉的深处，曾经有一座与生者之国并存的逝者之城。"] = "Глубоко в горах когда-то существовал Город Мертвых, сосуществовавший со Страной Живых.",
    ["巡星天赋的学徒推荐携带星云咏叹、灵界穿梭、星之定位、逃脱戏法进行战斗。"] = "Ученику с талантом «Звездный патруль» рекомендуется иметь при себе в бою «Небулу Арию», «Путешествие по духовному миру», «Звездное позиционирование» и «Уловку побега».",
    ["巨人一族内，“背叛者”的代名词是苏尼亚索列姆。"] = "Среди гигантов синонимом слова «предатель» является Сониатрим.",
    ["巨型尸骸截断去路，而它的身后，站着真正的操线者。"] = "Гигантский труп преграждает путь, а за ним стоит настоящий кукловод.",
    ["幻影守卫无法被治疗，但在周围没有敌方玩家时会缓慢回复生命值。"] = "Призрачных стражей невозможно вылечить, но они будут медленно восстанавливать здоровье, если поблизости нет вражеских игроков.",
    ["庄园深处传来心脏跳动的声音，猩红诡异的守护者徘徊在树下。"] = "Звук сердцебиения доносится из глубины поместья, а под деревьями бродит жуткий алый страж.",
    ["廷根中央广场，金币如雨。接住馈赠，避开陷阱，资本的诱惑，从不免费。"] = "Центральная площадь Тингена, золотые монеты, как дождь. Лови подарки, избегай ловушек; искушение капитала никогда не бывает бесплатным.",
    ["廷根位于鲁恩王国北方，属于阿霍瓦郡。"] = "Тинген расположен на севере королевства Лоен, входящего в состав округа Авва.",
    ["廷根再度面临危机，值夜者将使用封印物筑起最后的壁垒。"] = "Тинген вновь сталкивается с кризисом; Ночные Ястребы используют Запечатанные Артефакты, чтобы возвести последний барьер.",
    ["廷根号称“大学之城”，其中的廷根大学、霍伊大学是鲁恩知名高校。"] = "Тинген известен как «Город университетов», а университеты Тинген и Университет Хой являются известными высшими учебными заведениями Лоена.",
    ["廷根的射击俱乐部位于佐特兰街，有一块区域专属于值夜者。"] = "Стрелковый клуб в Тингене расположен на улица Зотланд, там есть зона, посвященная «Ночным ястребам».",
    ["廷根的某位小丑发来邀请——这是一局要命的扑克。"] = "Некто из Клоунов Тингена прислал приглашение — это смертельно опасная партия в покер.",
    ["开启一键辅助后，在战斗状态下长按普通攻击按键，即可自动释放技能。"] = "После включения поддержки одним касанием нажмите и удерживайте кнопку обычной атаки во время боя, чтобы автоматически применить навыки.",
    ["开局抢点，抢占先机！首次击杀守卫抢占归属获得额外积分！"] = "Захватите очки на старте, чтобы одержать верх! Первый, кто убьет Стража и завладеет им, получит дополнительные очки!",
    ["弗萨克人流淌着巨人的血，经常会梦见巨人王庭。"] = "Фейнапоттеры текут кровью гигантов и часто мечтают о дворе Короля гигантов.",
    ["当你从高空俯视这片草原时，可以看到爱心形状的公路。"] = "Если взглянуть на эти равнины с большой высоты, можно увидеть дорогу в форме сердца.",
    ["当你发现集火难以击杀敌方时，保护队友进行拆火，依靠伤害量取胜或许是个不错的办法。"] = "Когда вы обнаружите, что убить врага, сосредоточив огонь, сложно, хорошей стратегией может стать защита своих товарищей по команде, чтобы они могли их атаковать, и победа, основанная на наносимом уроне.",
    ["当发现自己形单影只时，不妨打开地图寻找己方势力成员位置。"] = "Когда вы окажетесь одни, возможно, вам захочется открыть карту, чтобы найти местонахождение членов вашей фракции.",
    ["当携带猩红遗物时，你可能已经成为其他猎人的目标，速去寻找猎杀管家提交！"] = "Имея при себе алую реликвию, вы могли стать мишенью для других охотников; поспешите найти Охотничьего Дворецкого, чтобы передать его!",
    ["忠诚的管家会永远守护威瑟尔家族，哪怕利用知识，利用生命。"] = "Верный дворецкий всегда будет защищать семью Уэтереллов, даже если для этого придется использовать знания или жизнь.",
    ["总有些事情，高于其他。"] = "Всегда есть вещи, которые превыше других.",
    ["感谢你，生命的源泉！赞美你，万物的母亲！"] = "Спасибо тебе, источник жизни! Слава Тебе, мать всего сущего!",
    ["慈善干事的伪善面具下，是压榨的深渊。解救劳工，让斩杀线在此终结。"] = "Под лицемерной маской сотрудника благотворительной организации скрывается бездна эксплуатации. Спасите рабочих и пусть очередь казней закончится здесь.",
    ["战士有输出和防御两种形态可以切换。"] = "У воинов есть две формы: мощность и защита, которые можно переключать.",
    ["战士途径：晨曦，遮蔽一切污秽。"] = "Путь Воина: Рассвет покрывает всю грязь.",
    ["战斗持续一段时间后，双方攻击力会逐步提升。"] = "По прошествии некоторого времени боя атака обеих сторон постепенно растет.",
    ["战略服会解锁职业专属的战略技能，对于战局有重大影响"] = "На стратегическом сервере открываются стратегические умения, эксклюзивные для классов, которые сильно влияют на ход сражений",
    ["战略服参与战斗即可提升军衔，获得提升和奖励"] = "Участвуйте в боях на стратегическом сервере, чтобы повышать воинское звание, получать повышения и награды",
    ["战略服是勇者的集结地，是荣誉的最高殿堂"] = "Стратегический сервер — место сбора храбрецов и высший чертог почета",
    ["所有人都会死，包括我。"] = "Все смертны, и я в том числе.",
    ["所有命运的馈赠，早已在暗中标注好了价格。"] = "На все подарки судьбы уже в темноте отмечены цены.",
    ["所有死亡的归宿，深藏灵界的地狱，万物终朽的见证，独属于死神的国度。"] = "Конечный пункт назначения всех, кто умирает, ад, спрятанный глубоко в Мире Духов, свидетель распада всего сущего – царство, принадлежащее исключительно Богу Смерти.",
    ["执怀表穿行酒馆的虚实扉页，完成未尽的净化仪式。"] = "Пройдитесь по страницам реальности и иллюзий таверны с карманными часами, завершив незавершенный ритуал очищения.",
    ["拉姆德古堡坐落于杂草丛生的山丘上，周围灌木密布。"] = "Замок Ламуд расположен на травянистом холме, окруженном густыми кустарниками.",
    ["据说卡尔·埃德加窥探到的禁忌知识，能够奴役和控制其他生物的心智。"] = "_\n\nГоворят, что запретные знания, за которыми подсмотрел Карл Эдгар, могут поработить и контролировать разум других существ.",
    ["救赎蔷薇建立的初衷是通过刺杀祂而拯救祂。"] = "Первоначальным намерением создания «Розового искупления» было спасти Его, убив Его.",
    ["救赎蔷薇，诞生于第三纪的隐秘组织，战争天使与命运天使都曾经是它的成员。"] = "«Искупление Розы», секретная организация, родившаяся в Третьей Эпохе, включала в себя как Ангела Войны, так и Ангела Судьбы.",
    ["斯林面包房不仅有好吃的廷根饼和柠檬蛋糕，还提供自制甜冰茶。"] = "Slin Bakery предлагает не только вкусное печенье Тинген и лимонный пирог, но и домашний сладкий чай со льдом.",
    ["时间在此凝固，世界永处黄昏。欢迎来到巨人王庭！"] = "Время здесь застыло, и мир навеки погружён в сумерки. Добро пожаловать во Двор Гигантского Короля!",
    ["晨曦天赋的战士推荐携带猎魔瞬斩，荣耀之斩，暮色连斩，巨剑斩击进行战斗。"] = "Воину с талантом «Рассвет» рекомендуется иметь при себе в бою «Мгновенный удар охотника на демонов», «Удар славы», «Сумеречный комбо-удар» и «Удар большим мечом».",
    ["智者天赋的窥秘人推荐携带光之折射、皇帝的新衣、窥秘之眼、岁月的棋局进行战斗。"] = "Тайноведцу с талантом «Мудрец» рекомендуется брать в бой «Преломление света», «Новое платье короля», «Око тайноведения» и «Гамбит веков».",
    ["曾有高位存在，渡过大海，在这里建立了一个隐秘的国度：夜之国。"] = "Когда-то существовало существо высокого уровня, которое пересекло море и основало здесь тайное королевство: Ночное Королевство.",
    ["最近廷根一段废弃的下水道中经常传来令人毛骨悚然的声音……"] = "В последнее время в заброшенной канализации в Тингене часто раздаются ужасающие звуки...",
    ["某天，来自贵族的报复摧毁了一切，唯有海伦娜小姐一人生还。"] = "В один роковой день месть аристократов разрушила всё, и лишь мисс Хелена осталась в живых.",
    ["查拉图的袭击影响了秘偶小镇，所有秘偶都在那一刻失控。"] = "Нападение Заратула затронуло маленький городок марионеток, и все марионетки в этот момент потеряли контроль.",
    ["棋手不妨囤些金币——回合结算的利息，积少成多。"] = "Игрокам стоит копить золотые монеты: проценты при подсчёте итогов раунда накапливаются.",
    ["欢迎来到众神之巅，你将在众神的注目下亮起刀兵，争夺荣光，见证力量。"] = "Добро пожаловать на Пик Богов, где вы возьмете в руки оружие под взором богов, поборетесь за славу и станете свидетелем силы.",
    ["欲念从不说谎，赌局引你入场。勘破子弹真相，成就欲望胜方。"] = "Желание никогда не лжет, игра втягивает вас. Увидьте правду пули, станьте победителем желания.",
    ["歌颂者途径：我以我身，沐浴烈阳。"] = "Путь Барда: Я купаюсь в Пылающем Солнце своим телом.",
    ["每一段旅行都有终点。"] = "У каждого странствия есть свой конец.",
    ["每个溺水的人都会挣扎。"] = "Каждый тонущий человек будет бороться.",
    ["每到工厂的发薪日，账单和洛克手下的讨债者们总会如期而至。"] = "В каждый день получки на фабрике счета и сборщики долгов Лока неизменно являлись точно в срок.",
    ["每年五月，种满苹果树的庄园都花香四溢。"] = "Каждый май усадьба, засаженная яблонями, наполняется ароматом.",
    ["比星空更崇高，比永恒更久远的黑夜女神。"] = "Богиня Вечной Ночи, более благородная, чем звездное небо, более вечная, чем вечность.",
    ["永暗蜡烛最初为阿兹克所制作，后被人利用，成为操纵村民献祭生命的工具。"] = "Свеча Вечной Тьмы была первоначально создана Азиком, но позже была использована другими, чтобы стать инструментом для манипулирования сельскими жителями, заставляя их жертвовать своими жизнями.",
    ["河与海教堂，位于北区，属于风暴之主教会。"] = "Церковь Реки и Моря, расположенная в Северном районе, принадлежит Церкви Повелителя Штормов.",
